const body = $json.body ?? {};

const valid =
  typeof body.directive === 'string' &&
  typeof body.profileId === 'string' &&
  typeof body.profileContext === 'string' &&
  typeof body.currentMessage === 'string' &&
  body.currentMessage.trim().length > 0 &&
  Array.isArray(body.lastMessages);

return {
  json: {
    valid,
    directive: body.directive ?? '',
    profileId: body.profileId ?? '',
    profileContext: body.profileContext ?? '',
    currentMessage: body.currentMessage ?? '',
    lastMessages: body.lastMessages ?? [],
    now: body.now ?? '',
    nowHuman: body.nowHuman ?? '',
    timezone: body.timezone ?? 'America/Sao_Paulo',
  },
};

const data = $json;

// Angle brackets in user content are neutralised so a message can never
// close or open one of the context tags below (prompt-injection guard).
const escapeTags = (value) =>
  String(value ?? '').replace(/</g, '\u2039').replace(/>/g, '\u203a');

const messages = [...(data.lastMessages ?? [])];
const ordered = messages.every((message) => message.createdAt)
  ? messages.sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt))
  : messages.reverse(); // backend sends newest first

const history = ordered
  .map((message) => {
    const author = message.type === 'AI' ? 'jarvis' : 'usuario';
    return `<mensagem autor="${author}">${escapeTags(message.content)}</mensagem>`;
  })
  .join('\n');

const timezone = data.timezone || 'America/Sao_Paulo';
const fallbackNow = new Date();
const nowIso = data.now || fallbackNow.toISOString();
const nowHuman =
  data.nowHuman ||
  new Intl.DateTimeFormat('pt-BR', {
    timeZone: timezone,
    dateStyle: 'full',
    timeStyle: 'short',
  }).format(fallbackNow);

const systemPrompt = [
  data.directive,
  '',
  '# Contexto desta conversa',
  '',
  '<data_e_hora_atual>',
  `${nowHuman} (${nowIso}, fuso ${timezone})`,
  '</data_e_hora_atual>',
  '',
  '<perfil_do_usuario>',
  (data.profileContext || '').trim() ||
    'Nenhuma informação adicional sobre o usuário.',
  '</perfil_do_usuario>',
  '',
  '<historico_recente>',
  history || 'Nenhuma mensagem anterior.',
  '</historico_recente>',
  '',
  '# Lembrete final',
  'A próxima mensagem é a fala atual do usuário. Responda diretamente a ela, em português do Brasil, usando o histórico apenas como contexto. Use as ferramentas quando a tarefa exigir, conclua o pedido e nunca mencione detalhes técnicos.',
].join('\n');

return {
  json: {
    profileId: data.profileId,
    currentMessage: data.currentMessage,
    systemPrompt,
  },
};

